/bin/bash -lc "python3 - <<'PY'
import pysam
bam=pysam.AlignmentFile('variant.status.q1.bam','rb')
# print sequences around 497-510 for representative reads covering
names=['READ_66611','READ_465051','READ_204279','READ_299295','READ_349569','READ_470520','READ_451779','READ_428868','READ_144249','READ_28724','READ_66470','READ_67034']
for name in names:
    try:
        r=bam.find(name.split()[0]) if False else None
    except: pass
for read in bam.fetch('chrX',154398300,154398600):
    if read.query_name not in names: continue
    # get aligned pairs for pos497-510 1-based => 0-based
    pairs=read.get_aligned_pairs(matches_only=False)
    bases=[]
    for target in range(154398497,154398511):
        q=None
        for qpos,rpos in pairs:
            if rpos==target-1:
                q=qpos; break
        if q is None:
            bases.append('-')
        else:
            bases.append(read.query_sequence[q])
    print(read.query_name, read.reference_start+1, read.cigarstring, ''.join(bases), 'query:', read.query_sequence)
PY"

